<pre class="xfBb-code" data-lang="">var Cookie = {
    get: function(name)
    {
        name = name;
        return $.cookie(name);
    },

    set: function(name, value, expires)
    {
        name = name;
        if(!expires)
        {
            expires = 315360000;
